import org.junit.Before;
import org.junit.Test;

public class AppVersionTest {

    private Ami ami;

    @Before
    public void setUp() {
        String amiName = "ami-1234567890abcdef";
        ami = new Ami(amiName, "ubuntu", "20.04");
    }

    @Test
    public void testParseName() {
        AppVersion appVersion = parseName(amiName);
        assertNotNull(appVersion);
        assertEquals("ami-1234567890abcdef", appVersion.getAmiName());
    }

    @Test
    public void testParseNameNullString() {
        AppVersion appVersion = parseName(null);
        assertThrows(NullPointerException.class, () -> appVersion.getAmiName());
    }

    @Test
    public void testGetPackageName() {
        assertEquals("ubuntu", ami.getVersion().getRpmPackage());
    }

    @Test
    public void testGetPackageNameNullString() {
        assertEquals("", ami.getVersion().getRpmPackage());
    }

    @Test
    public void testGetVersion() {
        assertEquals("20.04", ami.getVersion().getVersion());
    }

    @Test
    public void testGetVersionNullString() {
        assertEquals("", ami.getVersion().getVersion());
    }

    @Test
    public void testGetBuildJobName() {
        assertEquals("buildjob1", ami.getBuildJobName());
    }

    @Test
    public void testGetBuildJobNameNullString() {
        assertEquals("", ami.getBuildJobName());
    }

    @Test
    public void testGetCommit() {
        assertEquals("abc123", ami.getCommit());
    }

    @Test
    public void testGetCommitNullString() {
        assertEquals("", ami.getCommit());
    }

    @Test
    public void testGetChangelist() {
        assertEquals(null, ami.getBuildNumber().getChangelist());
    }

    @Test
    public void testEquals() {
        AmiVersion other = new AmiVersion(ami.getRpmPackage(), "20.04");
        assertTrue(AppVersion.class.isAssignableFrom(other.getClass()));
        AppVersion appVersion1 = parseName("ami-1234567890abcdef");
        AppVersion appVersion2 = new Ami("ami-567890123abc", "20.04");
        assertEquals(appVersion1, appVersion2);
    }

    @Test
    public void testHashCode() {
        AmiVersion other = new Ami("ami-1234567890abcdef", "20.04");
        int hashCode1 = AppVersion.class.hashCode();
        int hashCode2 = AppVersion.class.hashCode();
        assertEquals(hashCode1, hashCode2);
        AppVersion appVersion1 = parseName("ami-567890123abc", "20.04");
        int hashCode3 = AppVersion.class.hashCode();
        assertEquals(hashCode3, hashCode1);
    }

    @Test
    public void testGetAmiName() {
        String expected = "ami-1234567890abcdef";
        assertEquals(expected, ami.getAmiName());
    }
}
